def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2:
                continue
            # A marker replacing a cell of the green shape has at least two
            # orthogonal neighboring green cells; isolated outside markers do not.
            support = sum(0 <= r+dr < h and 0 <= c+dc < w and grid[r+dr][c+dc] == 3
                          for dr, dc in ((-1,0),(1,0),(0,-1),(0,1)))
            if support >= 2:
                for rr in range(max(0,r-1), min(h,r+2)):
                    for cc in range(max(0,c-1), min(w,c+2)):
                        if grid[rr][cc] != 2:
                            out[rr][cc] = 1
    return out
